import { z } from 'zod';
const positive=z.coerce.number().finite().positive().max(999999999999); const nonneg=z.coerce.number().finite().min(0).max(999999999999);
export const supplierSchema=z.object({code:z.string().trim().min(1).max(50),name:z.string().trim().min(1).max(180),legalName:z.string().trim().max(180).nullable().optional(),contactPerson:z.string().trim().max(120).nullable().optional(),phone:z.string().trim().max(50).nullable().optional(),email:z.string().trim().max(180).nullable().optional(),address:z.string().trim().max(500).nullable().optional(),taxIdentifier:z.string().trim().max(100).nullable().optional(),paymentTerms:z.string().trim().max(120).nullable().optional(),notes:z.string().trim().max(1000).nullable().optional(),status:z.enum(['ACTIVE','INACTIVE']).default('ACTIVE')});
export const supplierItemSchema=z.object({inventoryItemId:z.coerce.number().int().positive(),supplierItemCode:z.string().trim().max(100).nullable().optional(),purchaseUnitId:z.coerce.number().int().positive(),conversionToInventoryUnit:positive,unitPrice:nonneg,currency:z.string().trim().min(1).max(10).default('NPR'),minimumOrderQuantity:nonneg.default(0),leadTimeDays:z.coerce.number().int().min(0).max(3650).default(0),isPreferred:z.boolean().default(false),isActive:z.boolean().default(true),effectiveFrom:z.string().date().nullable().optional(),effectiveTo:z.string().date().nullable().optional()});
const poLine=z.object({supplierItemId:z.coerce.number().int().positive(),orderedQuantity:positive,unitPrice:nonneg.optional(),discount:nonneg.default(0),tax:nonneg.default(0),notes:z.string().trim().max(500).nullable().optional()});
export const createPOSchema=z.object({branchId:z.coerce.number().int().positive(),supplierId:z.coerce.number().int().positive(),expectedDeliveryDate:z.string().date().nullable().optional(),currency:z.string().trim().min(1).max(10).default('NPR'),notes:z.string().trim().max(1000).nullable().optional(),items:z.array(poLine).min(1).max(500)}).superRefine((v,ctx)=>{const ids=v.items.map(x=>x.supplierItemId);if(new Set(ids).size!==ids.length)ctx.addIssue({code:'custom',path:['items'],message:'Duplicate supplier item lines are not allowed'});});
export const receiveSchema=z.object({locationId:z.coerce.number().int().positive(),notes:z.string().trim().max(1000).nullable().optional(),items:z.array(z.object({purchaseOrderItemId:z.coerce.number().int().positive(),receivedQuantity:positive,acceptedQuantity:nonneg,rejectedQuantity:nonneg,notes:z.string().trim().max(500).nullable().optional()})).min(1).max(500)}).superRefine((v,ctx)=>{const ids=v.items.map(x=>x.purchaseOrderItemId);if(new Set(ids).size!==ids.length)ctx.addIssue({code:'custom',path:['items'],message:'Duplicate purchase order item lines are not allowed'});v.items.forEach((i,n)=>{if(i.acceptedQuantity+i.rejectedQuantity>i.receivedQuantity)ctx.addIssue({code:'custom',path:['items',n,'acceptedQuantity'],message:'Accepted plus rejected cannot exceed received quantity'});});});
export const listSchema=z.object({status:z.string().optional(),supplierId:z.coerce.number().int().positive().optional(),search:z.string().optional()});
