import {PoolConnection,RowDataPacket,ResultSetHeader} from 'mysql2/promise';
import {getDatabasePool} from '../../db/pool'; import {BadRequestError,ConflictError,ForbiddenError,NotFoundError} from '../../shared/errors';
import {inventoryRepository} from '../inventory/repository'; import {realtimePublisher} from '../../realtime/publisher'; import {PurchaseOrder,Supplier,SupplierItem} from './types';
const iso=(v:any)=>v instanceof Date?v.toISOString():String(v); const n=(v:any)=>Number(v||0);
function mapSupplier(r:any):Supplier{return {id:n(r.id),organizationId:n(r.organization_id),code:String(r.code),name:String(r.name),legalName:r.legal_name==null?null:String(r.legal_name),contactPerson:r.contact_person==null?null:String(r.contact_person),phone:r.phone==null?null:String(r.phone),email:r.email==null?null:String(r.email),address:r.address==null?null:String(r.address),taxIdentifier:r.tax_identifier==null?null:String(r.tax_identifier),paymentTerms:r.payment_terms==null?null:String(r.payment_terms),notes:r.notes==null?null:String(r.notes),status:r.status};}
function mapSupplierItem(r:any):SupplierItem{return {id:n(r.id),supplierId:n(r.supplier_id),inventoryItemId:n(r.inventory_item_id),inventoryItemName:String(r.inventory_item_name),supplierItemCode:r.supplier_item_code==null?null:String(r.supplier_item_code),purchaseUnitId:n(r.purchase_unit_id),purchaseUnitSymbol:String(r.purchase_unit_symbol),inventoryUnitId:n(r.inventory_unit_id),inventoryUnitSymbol:String(r.inventory_unit_symbol),conversionToInventoryUnit:n(r.conversion_to_inventory_unit),unitPrice:n(r.unit_price),currency:String(r.currency),minimumOrderQuantity:n(r.minimum_order_quantity),leadTimeDays:n(r.lead_time_days),isPreferred:Boolean(r.is_preferred),isActive:Boolean(r.is_active),effectiveFrom:r.effective_from==null?null:String(r.effective_from),effectiveTo:r.effective_to==null?null:String(r.effective_to)};}
export class PurchasingRepository{
 pool(){return getDatabasePool();}
 async branch(org:number,branch:number,conn?:PoolConnection){const db=conn||this.pool();const [r]=await db.execute<RowDataPacket[]>('SELECT id,is_active FROM branches WHERE id=? AND organization_id=?',[branch,org]);if(!r.length||!r[0].is_active)throw new ForbiddenError('Unauthorized or inactive branch','UNAUTHORIZED_BRANCH_ACCESS');}
 async listSuppliers(org:number){const [r]=await this.pool().execute<RowDataPacket[]>('SELECT * FROM suppliers WHERE organization_id=? ORDER BY status,name',[org]);return r.map(mapSupplier);}
 async createSupplier(org:number,data:any){try{const [x]=await this.pool().execute<ResultSetHeader>('INSERT INTO suppliers(organization_id,code,name,legal_name,contact_person,phone,email,address,tax_identifier,payment_terms,notes,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[org,data.code,data.name,data.legalName??null,data.contactPerson??null,data.phone??null,data.email??null,data.address??null,data.taxIdentifier??null,data.paymentTerms??null,data.notes??null,data.status]);const [r]=await this.pool().execute<RowDataPacket[]>('SELECT * FROM suppliers WHERE id=? AND organization_id=?',[x.insertId,org]);const s=mapSupplier(r[0]);realtimePublisher.publish({type:'supplier.created',organizationId:org,branchId:null,entityType:'supplier',entityId:s.id,data:{id:s.id,name:s.name}});return s;}catch(e:any){if(e?.errno===1062)throw new ConflictError('Supplier code already exists','SUPPLIER_DUPLICATE');throw e;}}
 async updateSupplier(org:number,id:number,data:any){const [r]=await this.pool().execute<RowDataPacket[]>('SELECT * FROM suppliers WHERE id=? AND organization_id=?',[id,org]);if(!r.length)throw new NotFoundError('Supplier not found','SUPPLIER_NOT_FOUND');const x=r[0];try{await this.pool().execute('UPDATE suppliers SET code=?,name=?,legal_name=?,contact_person=?,phone=?,email=?,address=?,tax_identifier=?,payment_terms=?,notes=?,status=?,updated_at=NOW() WHERE id=? AND organization_id=?',[data.code??x.code,data.name??x.name,data.legalName!==undefined?data.legalName:x.legal_name,data.contactPerson!==undefined?data.contactPerson:x.contact_person,data.phone!==undefined?data.phone:x.phone,data.email!==undefined?data.email:x.email,data.address!==undefined?data.address:x.address,data.taxIdentifier!==undefined?data.taxIdentifier:x.tax_identifier,data.paymentTerms!==undefined?data.paymentTerms:x.payment_terms,data.notes!==undefined?data.notes:x.notes,data.status??x.status,id,org]);const [u]=await this.pool().execute<RowDataPacket[]>('SELECT * FROM suppliers WHERE id=?',[id]);return mapSupplier(u[0]);}catch(e:any){if(e?.errno===1062)throw new ConflictError('Supplier code already exists','SUPPLIER_DUPLICATE');throw e;}}
 async supplierItemPriceHistory(org:number,branch:number,supplierId:number,supplierItemId:number){await this.supplierItems(org,branch,supplierId);const [r]=await this.pool().execute<RowDataPacket[]>('SELECT h.* FROM supplier_item_price_history h JOIN supplier_items si ON si.id=h.supplier_item_id WHERE h.organization_id=? AND si.branch_id=? AND si.supplier_id=? AND h.supplier_item_id=? ORDER BY h.effective_from DESC,h.id DESC',[org,branch,supplierId,supplierItemId]);return r.map(x=>({id:n(x.id),supplierItemId:n(x.supplier_item_id),unitPrice:n(x.unit_price),currency:String(x.currency),effectiveFrom:String(x.effective_from),createdAt:iso(x.created_at)}));}
 async supplierItems(org:number,branch:number,supplierId:number){const [r]=await this.pool().execute<RowDataPacket[]>(`SELECT si.*,ii.name inventory_item_name,ii.unit_id inventory_unit_id,iu.symbol inventory_unit_symbol,pu.symbol purchase_unit_symbol FROM supplier_items si JOIN inventory_items ii ON ii.id=si.inventory_item_id JOIN units_of_measure pu ON pu.id=si.purchase_unit_id JOIN units_of_measure iu ON iu.id=ii.unit_id WHERE si.organization_id=? AND si.branch_id=? AND si.supplier_id=? ORDER BY si.is_preferred DESC,ii.name`,[org,branch,supplierId]);return r.map(mapSupplierItem);}
 async upsertSupplierItem(org:number,branch:number,supplierId:number,data:any){const [s]=await this.pool().execute<RowDataPacket[]>('SELECT id,status FROM suppliers WHERE id=? AND organization_id=?',[supplierId,org]);if(!s.length)throw new NotFoundError('Supplier not found','SUPPLIER_NOT_FOUND');const [it]=await this.pool().execute<RowDataPacket[]>('SELECT id,organization_id,branch_id,unit_id,name FROM inventory_items WHERE id=? AND organization_id=? AND branch_id=?',[data.inventoryItemId,org,branch]);if(!it.length)throw new NotFoundError('Inventory item not found','INVENTORY_ITEM_NOT_FOUND');const [pu]=await this.pool().execute<RowDataPacket[]>('SELECT id,is_active FROM units_of_measure WHERE id=? AND is_active=TRUE',[data.purchaseUnitId]);if(!pu.length)throw new BadRequestError('Invalid purchase unit','INVALID_PURCHASE_UNIT');const [existing]=await this.pool().execute<RowDataPacket[]>('SELECT id,unit_price,currency FROM supplier_items WHERE organization_id=? AND branch_id=? AND supplier_id=? AND inventory_item_id=?',[org,branch,supplierId,data.inventoryItemId]);let id:number;if(existing.length){id=n(existing[0].id);await this.pool().execute('UPDATE supplier_items SET supplier_item_code=?,purchase_unit_id=?,conversion_to_inventory_unit=?,unit_price=?,currency=?,minimum_order_quantity=?,lead_time_days=?,is_preferred=?,is_active=?,effective_from=?,effective_to=?,updated_at=NOW() WHERE id=?',[data.supplierItemCode??null,data.purchaseUnitId,data.conversionToInventoryUnit,data.unitPrice,data.currency,data.minimumOrderQuantity,data.leadTimeDays,data.isPreferred?1:0,data.isActive===false?0:1,data.effectiveFrom??null,data.effectiveTo??null,id]);if(n(existing[0].unitPrice)!==n(data.unitPrice)||String(existing[0].currency)!==String(data.currency))await this.pool().execute('INSERT INTO supplier_item_price_history(organization_id,supplier_item_id,unit_price,currency,effective_from) VALUES(?,?,?,?,COALESCE(?,CURRENT_DATE))',[org,id,data.unitPrice,data.currency,data.effectiveFrom??null]);}else{const [x]=await this.pool().execute<ResultSetHeader>('INSERT INTO supplier_items(organization_id,branch_id,supplier_id,inventory_item_id,supplier_item_code,purchase_unit_id,conversion_to_inventory_unit,unit_price,currency,minimum_order_quantity,lead_time_days,is_preferred,is_active,effective_from,effective_to) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[org,branch,supplierId,data.inventoryItemId,data.supplierItemCode??null,data.purchaseUnitId,data.conversionToInventoryUnit,data.unitPrice,data.currency,data.minimumOrderQuantity,data.leadTimeDays,data.isPreferred?1:0,data.isActive===false?0:1,data.effectiveFrom??null,data.effectiveTo??null]);id=n(x.insertId);await this.pool().execute('INSERT INTO supplier_item_price_history(organization_id,supplier_item_id,unit_price,currency,effective_from) VALUES(?,?,?,?,COALESCE(?,CURRENT_DATE))',[org,id,data.unitPrice,data.currency,data.effectiveFrom??null]);}
 const list=await this.supplierItems(org,branch,supplierId);return list.find(x=>x.id===id)!;}
 async generatePO(org:number,branch:number,conn:PoolConnection){await this.branch(org,branch,conn);await conn.execute('INSERT INTO purchase_order_sequences(organization_id,branch_id,next_number) VALUES(?,?,1) ON DUPLICATE KEY UPDATE next_number=next_number',[org,branch]);const [r]=await conn.execute<RowDataPacket[]>('SELECT next_number FROM purchase_order_sequences WHERE organization_id=? AND branch_id=? FOR UPDATE',[org,branch]);const seq=n(r[0].next_number);await conn.execute('UPDATE purchase_order_sequences SET next_number=next_number+1 WHERE organization_id=? AND branch_id=?',[org,branch]);return `PO-${String(branch).padStart(3,'0')}-${String(seq).padStart(6,'0')}`;}
 async getPO(org:number,branch:number,id:number,conn?:PoolConnection){const db=conn||this.pool();const [h]=await db.execute<RowDataPacket[]>(`SELECT po.*,s.name supplier_name FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id WHERE po.id=? AND po.organization_id=? AND po.branch_id=?`,[id,org,branch]);if(!h.length)throw new NotFoundError('Purchase order not found','PURCHASE_ORDER_NOT_FOUND');const [lines]=await db.execute<RowDataPacket[]>(`SELECT poi.*,pu.symbol purchase_unit_symbol,iu.symbol inventory_unit_symbol,(poi.ordered_quantity-poi.received_quantity) remaining_quantity FROM purchase_order_items poi JOIN units_of_measure pu ON pu.id=poi.purchase_unit_id JOIN units_of_measure iu ON iu.id=poi.inventory_unit_id WHERE poi.purchase_order_id=? ORDER BY poi.id`,[id]);return {...h[0],id:n(h[0].id),organizationId:n(h[0].organization_id),branchId:n(h[0].branch_id),supplierId:n(h[0].supplier_id),supplierName:String(h[0].supplier_name),subtotal:n(h[0].subtotal),discount:n(h[0].discount),tax:n(h[0].tax),grandTotal:n(h[0].grand_total),createdBy:n(h[0].created_by),approvedBy:h[0].approved_by==null?null:n(h[0].approved_by),approvedAt:h[0].approved_at?iso(h[0].approved_at):null,createdAt:iso(h[0].created_at),updatedAt:iso(h[0].updated_at),items:lines.map(x=>({id:n(x.id),inventoryItemId:n(x.inventory_item_id),descriptionSnapshot:String(x.description_snapshot),purchaseUnitSymbol:String(x.purchase_unit_symbol),inventoryUnitSymbol:String(x.inventory_unit_symbol),conversionFactor:n(x.conversion_factor),orderedQuantity:n(x.ordered_quantity),receivedQuantity:n(x.received_quantity),acceptedQuantity:n(x.accepted_quantity),rejectedQuantity:n(x.rejected_quantity),remainingQuantity:n(x.remaining_quantity),unitPrice:n(x.unit_price),discount:n(x.discount),tax:n(x.tax),lineTotal:n(x.line_total),notes:x.notes==null?null:String(x.notes)}))} as PurchaseOrder;}
 async listPOs(org:number,branch:number,filter:any){await this.branch(org,branch);const clauses=['po.organization_id=?','po.branch_id=?'];const params:any[]=[org,branch];if(filter.status){clauses.push('po.status=?');params.push(filter.status);}if(filter.supplierId){clauses.push('po.supplier_id=?');params.push(filter.supplierId);}if(filter.search){clauses.push('(po.po_number LIKE ? OR s.name LIKE ?)');params.push(`%${filter.search}%`,`%${filter.search}%`);}const [r]=await this.pool().execute<RowDataPacket[]>(`SELECT po.*,s.name supplier_name,(SELECT COUNT(*) FROM purchase_order_items x WHERE x.purchase_order_id=po.id) item_count FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id WHERE ${clauses.join(' AND ')} ORDER BY po.id DESC`,params);return r.map(x=>({id:n(x.id),poNumber:String(x.po_number),supplierId:n(x.supplier_id),supplierName:String(x.supplier_name),branchId:n(x.branch_id),status:x.status,orderDate:String(x.order_date),grandTotal:n(x.grand_total),currency:String(x.currency),itemCount:n(x.item_count)}));}
 async createPO(org:number,branch:number,user:number,data:any){const conn=await this.pool().getConnection();try{await conn.beginTransaction();await this.branch(org,branch,conn);const [s]=await conn.execute<RowDataPacket[]>('SELECT id,name,status FROM suppliers WHERE id=? AND organization_id=? FOR UPDATE',[data.supplierId,org]);if(!s.length||s[0].status!=='ACTIVE')throw new ConflictError('Supplier is unavailable','SUPPLIER_UNAVAILABLE');const ids=data.items.map((i:any)=>i.supplierItemId);const [sis]=await conn.query<RowDataPacket[]>(`SELECT si.*,ii.name inventory_item_name,ii.unit_id inventory_unit_id FROM supplier_items si JOIN inventory_items ii ON ii.id=si.inventory_item_id WHERE si.organization_id=? AND si.branch_id=? AND si.supplier_id=? AND si.id IN (${ids.map(()=>'?').join(',')}) AND si.is_active=TRUE FOR UPDATE`,[org,branch,data.supplierId,...ids]);const by=new Map(sis.map(x=>[n(x.id),x]));if(by.size!==ids.length)throw new BadRequestError('One or more supplier items are invalid or inactive','INVALID_SUPPLIER_ITEM');let subtotal=0,discount=0,tax=0;const lines=[];for(const input of data.items){const si=by.get(n(input.supplierItemId))!;const qty=n(input.orderedQuantity),price=input.unitPrice===undefined?n(si.unit_price):n(input.unitPrice);if(qty<n(si.minimum_order_quantity))throw new BadRequestError(`Quantity for ${si.inventory_item_name} is below supplier minimum order quantity`,'MINIMUM_ORDER_QUANTITY');const gross=qty*price,d=n(input.discount),t=n(input.tax),line=Math.max(0,gross-d)+t;subtotal+=gross;discount+=d;tax+=t;lines.push({si,qty,price,d,t,line});}const poNumber=await this.generatePO(org,branch,conn);const grand=subtotal-discount+tax;const [h]=await conn.execute<ResultSetHeader>('INSERT INTO purchase_orders(organization_id,branch_id,supplier_id,po_number,status,order_date,expected_delivery_date,currency,subtotal,discount,tax,grand_total,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[org,branch,data.supplierId,poNumber,'DRAFT',new Date().toISOString().slice(0,10),data.expectedDeliveryDate??null,data.currency,subtotal,discount,tax,grand,data.notes??null,user]);for(const l of lines)await conn.execute('INSERT INTO purchase_order_items(organization_id,branch_id,purchase_order_id,inventory_item_id,description_snapshot,purchase_unit_id,inventory_unit_id,conversion_factor,ordered_quantity,unit_price,discount,tax,line_total,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[org,branch,h.insertId,l.si.inventory_item_id,l.si.inventory_item_name,l.si.purchase_unit_id,l.si.inventory_unit_id,l.si.conversion_to_inventory_unit,l.qty,l.price,l.d,l.t,l.line,l.notes??null]);await conn.commit();const out=await this.getPO(org,branch,n(h.insertId));realtimePublisher.publish({type:'purchase_order.created',organizationId:org,branchId:branch,entityType:'purchase_order',entityId:out.id,data:{poNumber:out.poNumber,status:out.status,total:out.grandTotal}});return out;}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
 async transition(org:number,branch:number,user:number,id:number,target:string){const conn=await this.pool().getConnection();try{await conn.beginTransaction();const [r]=await conn.execute<RowDataPacket[]>('SELECT * FROM purchase_orders WHERE id=? AND organization_id=? AND branch_id=? FOR UPDATE',[id,org,branch]);if(!r.length)throw new NotFoundError('Purchase order not found','PURCHASE_ORDER_NOT_FOUND');const from=String(r[0].status);const allowed:Record<string,string[]>={PENDING_APPROVAL:['DRAFT'],APPROVED:['PENDING_APPROVAL'],ORDERED:['APPROVED'],CANCELLED:['DRAFT','PENDING_APPROVAL','APPROVED','ORDERED'],CLOSED:['RECEIVED']};if(!allowed[target]?.includes(from))throw new ConflictError(`Cannot transition purchase order from ${from} to ${target}`,'INVALID_PO_TRANSITION');const [rc]=await conn.execute<RowDataPacket[]>('SELECT COALESCE(SUM(received_quantity),0) received_total,COALESCE(SUM(ordered_quantity),0) ordered_total FROM purchase_order_items WHERE purchase_order_id=?',[id]);if(target==='CANCELLED'&&n(rc[0].received_total)>0){}await conn.execute('UPDATE purchase_orders SET status=?,approved_by=IF(?="APPROVED",?,approved_by),approved_at=IF(?="APPROVED",NOW(),approved_at),cancelled_by=IF(?="CANCELLED",?,cancelled_by),cancelled_at=IF(?="CANCELLED",NOW(),cancelled_at),updated_at=NOW() WHERE id=?',[target,target,user,target,target,user,target,id]);await conn.commit();const out=await this.getPO(org,branch,id);realtimePublisher.publish({type:target==='APPROVED'?'purchase_order.approved':target==='CANCELLED'?'purchase_order.cancelled':target==='ORDERED'?'purchase_order.ordered':'purchase_order.updated',organizationId:org,branchId:branch,entityType:'purchase_order',entityId:id,data:{status:target,poNumber:out.poNumber}});return out;}catch(e){await conn.rollback();throw e;}finally{conn.release();}}
 async receive(org:number,branch:number,user:number,poId:number,data:any, idempotencyKey:string, requestHash:string){const conn=await this.pool().getConnection();try{await conn.beginTransaction();const [poLock]=await conn.execute<RowDataPacket[]>('SELECT id FROM purchase_orders WHERE id=? AND organization_id=? AND branch_id=? FOR UPDATE',[poId,org,branch]);if(!poLock.length)throw new NotFoundError('Purchase order not found','PURCHASE_ORDER_NOT_FOUND');const [existing]=await conn.execute<RowDataPacket[]>('SELECT id,purchase_order_id,request_hash FROM purchase_receipts WHERE organization_id=? AND branch_id=? AND idempotency_key=? LIMIT 1 FOR UPDATE',[org,branch,idempotencyKey]);if(existing.length){const row=existing[0];if(n(row.purchase_order_id)!==poId||(row.request_hash!=null&&String(row.request_hash)!==requestHash))throw new ConflictError('Idempotency key was already used for a different receipt','IDEMPOTENCY_KEY_CONFLICT');await conn.commit();return this.getPO(org,branch,poId);}const po=await this.getPO(org,branch,poId,conn);if(!['ORDERED','PARTIALLY_RECEIVED'].includes(po.status))throw new ConflictError('Purchase order is not eligible for receiving','PO_NOT_RECEIVABLE');await inventoryRepository.validateLocation(conn,org,branch,n(data.locationId),true);const [receipt]=await conn.execute<ResultSetHeader>('INSERT INTO purchase_receipts(organization_id,branch_id,purchase_order_id,supplier_id,received_by,idempotency_key,request_hash,notes) VALUES(?,?,?,?,?,?,?,?)',[org,branch,poId,po.supplierId,user,idempotencyKey,requestHash,data.notes??null]);let allReceived=true;for(const line of data.items){const item=po.items.find(x=>x.id===n(line.purchaseOrderItemId));if(!item)throw new BadRequestError('Receipt line does not belong to purchase order','INVALID_RECEIPT_ITEM');const remaining=Math.max(0,item.orderedQuantity-item.receivedQuantity);const received=n(line.receivedQuantity),accepted=n(line.acceptedQuantity),rejected=n(line.rejectedQuantity);if(received<=0||received>remaining)throw new BadRequestError(`Invalid receiving quantity for ${item.descriptionSnapshot}`,'INVALID_RECEIVING_QUANTITY');if(accepted<0||rejected<0||accepted+rejected>received)throw new BadRequestError('Accepted plus rejected exceeds received','INVALID_RECEIPT_QUANTITY');const inventoryQty=accepted*item.conversionFactor;await conn.execute('INSERT INTO purchase_receipt_items(organization_id,branch_id,receipt_id,purchase_order_item_id,ordered_quantity,received_quantity,accepted_quantity,rejected_quantity,inventory_quantity,unit_price,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[org,branch,receipt.insertId,item.id,item.orderedQuantity,received,accepted,rejected,inventoryQty,item.unitPrice,line.notes??null]);const acquisitionPerPurchaseUnit=item.orderedQuantity>0?item.lineTotal/item.orderedQuantity:item.unitPrice;const acquisitionPerInventoryUnit=item.conversionFactor>0?acquisitionPerPurchaseUnit/item.conversionFactor:0;await inventoryRepository.updateWeightedAverageCost(org,branch,item.inventoryItemId,inventoryQty,acquisitionPerInventoryUnit,conn);await inventoryRepository.mutateStock(org,branch,item.inventoryItemId,n(data.locationId),inventoryQty,'PURCHASE_RECEIPT',`Purchase receipt ${receipt.insertId}`,user,'PURCHASE_RECEIPT',n(receipt.insertId),conn);await conn.execute('UPDATE purchase_order_items SET received_quantity=received_quantity+?,accepted_quantity=accepted_quantity+?,rejected_quantity=rejected_quantity+? WHERE id=?',[received,accepted,rejected,item.id]);if(received<remaining)allReceived=false;}const [tot]=await conn.execute<RowDataPacket[]>('SELECT COALESCE(SUM(received_quantity),0) received,COALESCE(SUM(ordered_quantity),0) ordered FROM purchase_order_items WHERE purchase_order_id=?',[poId]);const status=n(tot[0].received)>=n(tot[0].ordered)?'RECEIVED':'PARTIALLY_RECEIVED';await conn.execute('UPDATE purchase_orders SET status=?,updated_at=NOW() WHERE id=?',[status,poId]);await conn.commit();const out=await this.getPO(org,branch,poId);realtimePublisher.publish({type:'purchase_receipt.created',organizationId:org,branchId:branch,entityType:'purchase_receipt',entityId:n(receipt.insertId),data:{purchaseOrderId:poId,poNumber:out.poNumber,status}});
realtimePublisher.publish({type:'purchase_order.updated',organizationId:org,branchId:branch,entityType:'purchase_order',entityId:poId,data:{poNumber:out.poNumber,status}});realtimePublisher.publish({type:'inventory.stock_changed',organizationId:org,branchId:branch,entityType:'inventory_balance',entityId:n(receipt.insertId),data:{purchaseOrderId:poId}});return out;}catch(e:any){await conn.rollback();if(e?.errno===1062){const [rows]=await this.pool().execute<RowDataPacket[]>('SELECT purchase_order_id,request_hash FROM purchase_receipts WHERE organization_id=? AND branch_id=? AND idempotency_key=? LIMIT 1',[org,branch,idempotencyKey]);if(rows.length){if(n(rows[0].purchase_order_id)!==poId||(rows[0].request_hash!=null&&String(rows[0].request_hash)!==requestHash))throw new ConflictError('Idempotency key was already used for a different receipt','IDEMPOTENCY_KEY_CONFLICT');return this.getPO(org,branch,poId);}}throw e;}finally{conn.release();}}
 async receipts(org:number,branch:number,poId:number){await this.getPO(org,branch,poId);const [r]=await this.pool().execute<RowDataPacket[]>('SELECT pr.*,po.po_number FROM purchase_receipts pr JOIN purchase_orders po ON po.id=pr.purchase_order_id WHERE pr.organization_id=? AND pr.branch_id=? AND pr.purchase_order_id=? ORDER BY pr.id DESC',[org,branch,poId]);return r.map(x=>({id:n(x.id),purchaseOrderId:n(x.purchase_order_id),poNumber:String(x.po_number),status:x.status,receivedBy:n(x.received_by),receivedAt:iso(x.received_at),createdAt:iso(x.created_at)}));}
 async listReceipts(org:number,branch:number){const [r]=await this.pool().execute<RowDataPacket[]>('SELECT pr.*,po.po_number,s.name supplier_name FROM purchase_receipts pr JOIN purchase_orders po ON po.id=pr.purchase_order_id JOIN suppliers s ON s.id=pr.supplier_id WHERE pr.organization_id=? AND pr.branch_id=? ORDER BY pr.id DESC LIMIT 200',[org,branch]);return r.map(x=>({id:n(x.id),purchaseOrderId:n(x.purchase_order_id),poNumber:String(x.po_number),supplierName:String(x.supplier_name),receivedBy:n(x.received_by),receivedAt:iso(x.received_at)}));}
}
export const purchasingRepository=new PurchasingRepository();
